from typing import List, Tuple

def max_value_on_paths(N: int, grid_values: List[Tuple[int, int, int]]) -> int:
    # Create a grid to store the values
    grid = [[0] * N for _ in range(N)]

    # Populate the grid with the given values
    for x, y, value in grid_values:
        if x == 0 and y == 0 and value == 0:
            break
        grid[x-1][y-1] = value

    # Initialize memoization table
    memo = {}

    # Define the recursive function with memoization
    def dp(x1, y1, x2):
        y2 = x1 + y1 - x2
        if x1 == N-1 and y1 == N-1:
            return grid[x1][y1]
        if x1 > N-1 or y1 > N-1 or x2 > N-1 or y2 > N-1 or grid[x1][y1] == -1:
            return float('-inf')
        if (x1, y1, x2) in memo:
            return memo[(x1, y1, x2)]

        # Value collected at the current position
        current_value = grid[x1][y1] + (grid[x2][y2] if x2 != x1 or y2 != y1 else 0)

        # Recursively calculate the maximum value for the next steps
        result = max(
            dp(x1+1, y1, x2+1),
            dp(x1+1, y1, x2),
            dp(x1, y1+1, x2+1),
            dp(x1, y1+1, x2)
        )

        # Store the result in the memoization table
        memo[(x1, y1, x2)] = current_value + result
        return memo[(x1, y1, x2)]

    # Mark all invalid positions as -1
    for x in range(N):
        for y in range(N):
            if grid[x][y] == 0 and (x, y) != (0, 0):
                grid[x][y] = -1

    # Start the DP from the top-left corner
    return dp(1, 1, 1)
