def max_product(num_str: str, N: int, K: int) -> int:
    from functools import lru_cache

    @lru_cache(None)
    def dfs(index, k):
        if k == 0:
            return int(num_str[index:])

        max_product = 0
        for next_index in range(index + 1, N):
            left_part = int(num_str[index:next_index])
            right_part = dfs(next_index, k - 1)
            max_product = max(max_product, left_part * right_part)

        return max_product

    return dfs(0, K)
```

