        total = 0
        for i, char in enumerate(isbn.replace('-', '')):
            if char.isdigit():
                total += int(char) * (10 - i)
            elif char == 'X':
                total += 10 * (10 - i)
            else:
                return -1  # Invalid character
        return total % 11

    isbn_parts = isbn.split('-')
    if len(isbn_parts) != 5 or len(isbn_parts[3]) != 5:
        return isbn  # Invalid format

    index = isbn.rindex('X') if 'X' in isbn else isbn.rindex('-X') if '-X' in isbn else -1
    if index != -1:
        # Verify or correct the checksum digit
        calculated_checksum = calculate_checksum(isbn[:index + 1])
        if calculated_checksum == 0:
            return isbn[:index] + str('X')
        elif calculated_checksum == 1:
            return isbn[:index] + '0'
        else:
            return isbn

    # Verify the checksum
    calculated_checksum = calculate_checksum(isbn)
    if calculated_checksum == 0:
        return "Right"
    else:
