    max_horizontal_separations = [0] * M
    max_vertical_separations = [0] * N

    for (Xi, Yi, Pi, Qi) in chatting_pairs:
        if Xi == Pi:  # Vertical chat
            left = min(Yi, Qi)
            right = max(Yi, Qi)
            for col in range(N):
                if left < col < right:
                    max_horizontal_separations[Xi-1] += 1
        elif Yi == Qi:  # Horizontal chat
            top = min(Xi, Pi)
            bottom = max(Xi, Pi)
            for row in range(M):
                if top < row < bottom:
                    max_vertical_separations[Yi-1] += 1

    selected_horizontal = []
    for i in range(K):
        max_index = max_vertical_separations.index(max(max_vertical_separations))
        selected_horizontal.append(str(max_index + 1))
        max_vertical_separations[max_index] = -1

    selected_vertical = []
    for i in range(L):
        max_index = max_horizontal_separations.index(max(max_horizontal_separations))
        selected_vertical.append(str(max_index + 1))
        max_horizontal_separations[max_index] = -1

    return ' '.join(selected_horizontal), ' '.join(selected_vertical)
