    visited = set([n])
    while queue:
        current = queue.popleft()
        for digit, new_digit in rules:
            str_current = str(current)
            for i in range(len(str_current)):
                if int(str_current[i]) == digit:
                    transformed = int(str_current[:i] + str(new_digit) + str_current[i+1:])
                    if transformed not in visited:
                        visited.add(transformed)
                        queue.append(transformed)
