def generate_numbers(n, rules) -> int:
    from collections import deque

    def apply_rules(num, rules):
        num_str = str(num)
        new_nums = set([num])
        for i in range(len(num_str)):
            for x, y in rules:
                new_num_str = num_str[:i] + str(y) + num_str[i+1:]
                if int(new_num_str) not in new_nums:
                    new_nums.add(int(new_num_str))
        return new_nums

    visited = set()
    queue = deque([n])
    unique_count = 0

    while queue:
        current_num = queue.popleft()
        if current_num not in visited:
            visited.add(current_num)
            unique_count += 1
            queue.extend(apply_rules(current_num, rules))

    return unique_count

