def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7

    # Initialize a DP array where dp[i][j] represents the number of ways to arrange j pots using the first i types
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1  # There's one way to arrange 0 pots using 0 types of flowers

    for i in range(1, n + 1):
        for j in range(m + 1):
            for k in range(a[i - 1] + 1):
                if j >= k:
                    dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD

    return dp[n][m]
